"""Tables and test vectors for internal/idna2003, taken from CPython itself.

The Python release converts host names with name.encode("idna"), the IDNA
2003 codec of the standard library (encodings.idna). The Go package
reproduces it bit for bit, so every table is read from the same
interpreter instead of from the Unicode data files: nameprep uses
stringprep (Unicode 3.2.0), str.lower() of the running Unicode version
and the NFKC of unicodedata.ucd_3_2_0, whose combining classes and
composition pairs come from the current Unicode version.

Usage, from the repository root with the project virtual environment:

    .venv/bin/python -I internal/idna2003/testdata/oracle.py tables \
        > internal/idna2003/tables.go
    .venv/bin/python -I internal/idna2003/testdata/oracle.py vectors \
        tests/golden/fixture/legacy/*.tar \
        > internal/idna2003/testdata/python_vectors.jsonl
    .venv/bin/python -I internal/idna2003/testdata/oracle.py digests \
        > internal/idna2003/testdata/python_digests.json
    .venv/bin/python -I internal/idna2003/testdata/oracle.py serve

"serve" reads one JSON string per line and answers with the encoded name
or null for an error; the Go tests use it as a live oracle.
"""

import hashlib
import json
import random
import sys
import tarfile
import unicodedata

import stringprep

ucd = unicodedata.ucd_3_2_0
SURROGATES = range(0xD800, 0xE000)


def encode(name):
    try:
        return name.encode("idna").decode("ascii")
    except UnicodeError:
        return None


def codepoints():
    for cp in range(0x110000):
        if cp not in SURROGATES:
            yield cp


def spans(pred):
    out, start, prev = [], None, None
    for cp in codepoints():
        if pred(chr(cp)):
            if start is not None and cp == prev + 1:
                prev = cp
                continue
            if start is not None:
                out.append((start, prev))
            start = prev = cp
    if start is not None:
        out.append((start, prev))
    return out


def prohibited(c):
    return any(f(c) for f in (
        stringprep.in_table_c12, stringprep.in_table_c22, stringprep.in_table_c3,
        stringprep.in_table_c4, stringprep.in_table_c5, stringprep.in_table_c6,
        stringprep.in_table_c7, stringprep.in_table_c8, stringprep.in_table_c9))


def hangul(cp):
    return 0xAC00 <= cp < 0xAC00 + 11172


def b2_map():
    return {cp: m for cp in codepoints()
            if not stringprep.in_table_b1(chr(cp))
            and (m := stringprep.map_table_b2(chr(cp))) != chr(cp)}


def nfkd_map():
    return {cp: d for cp in codepoints()
            if not hangul(cp) and (d := ucd.normalize("NFKD", chr(cp))) != chr(cp)}


def ccc_spans():
    out = []
    for cp in codepoints():
        k = unicodedata.combining(chr(cp))
        if not k:
            continue
        if out and out[-1][1] == cp - 1 and out[-1][2] == k:
            out[-1][1] = cp
        else:
            out.append([cp, cp, k])
    return out


def composition_pairs():
    """The NFC pairs of the current Unicode version as makeunicodedata.py
    builds them: canonical two-character decompositions whose first
    character is a starter, without the composition exclusions. A
    character outside the exclusions is its own NFC."""
    pairs = []
    for cp in codepoints():
        d = unicodedata.decomposition(chr(cp))
        if not d or d.startswith("<"):
            continue
        parts = [int(p, 16) for p in d.split()]
        if len(parts) != 2 or unicodedata.combining(chr(parts[0])):
            continue
        if unicodedata.normalize("NFC", chr(cp)) == chr(cp):
            pairs.append((parts[0], parts[1], cp))
    return sorted(pairs)


def check_assumptions():
    # The ACE prefix test lower-cases the label with str.lower(); the Go
    # code folds ASCII only, which is the same when no other character
    # lower-cases to text containing "x", "n" or "-".
    for cp in codepoints():
        if cp >= 0x80 and set(chr(cp).lower()) & set("xnXN-"):
            raise SystemExit("U+%04X lower-cases to %r" % (cp, chr(cp).lower()))


def go_string(s):
    out = []
    for ch in s:
        cp = ord(ch)
        if ch == '"' or ch == "\\":
            out.append("\\" + ch)
        elif 0x20 <= cp < 0x7F:
            out.append(ch)
        elif cp <= 0xFFFF:
            out.append("\\u%04x" % cp)
        else:
            out.append("\\U%08x" % cp)
    return '"' + "".join(out) + '"'


def emit_rows(lines, items, per_line):
    for i in range(0, len(items), per_line):
        lines.append("\t" + " ".join(items[i:i + per_line]))


def tables():
    check_assumptions()
    lines = [
        "// Code generated by testdata/oracle.py tables; DO NOT EDIT.",
        "",
        "// Source: CPython %s, Unicode %s, stringprep and NFKC of UCD %s."
        % (sys.version.split()[0], unicodedata.unidata_version, ucd.unidata_version),
        "",
        "package idna2003",
        "",
        "// unicodeVersion is the Unicode version of str.lower() and of the",
        "// combining classes and composition pairs the tables were taken from.",
        'const unicodeVersion = "%s"' % unicodedata.unidata_version,
        "",
    ]
    sets = [
        ("mapToNothing", "is table B.1 of RFC 3454 (mapped to nothing).", stringprep.in_table_b1),
        ("prohibitedChars", "are tables C.1.2, C.2.2 and C.3 to C.9: the characters nameprep refuses.", prohibited),
        ("randALCat", "is table D.1: characters with bidirectional class R or AL.", stringprep.in_table_d1),
        ("lCat", "is table D.2: characters with bidirectional class L.", stringprep.in_table_d2),
    ]
    for name, doc, pred in sets:
        lines.append("// %s %s" % (name, doc))
        lines.append("var %s = []span{" % name)
        emit_rows(lines, ["{0x%x, 0x%x}," % s for s in spans(pred)], 6)
        lines += ["}", ""]
    lines.append("// caseMap is map_table_b2 of stringprep (table B.2): every character it")
    lines.append("// changes, with the result.")
    lines.append("var caseMap = []mapping{")
    emit_rows(lines, ["{0x%x, %s}," % (cp, go_string(m)) for cp, m in sorted(b2_map().items())], 4)
    lines += ["}", ""]
    lines.append("// decompositions is the full compatibility decomposition (NFKD) of every")
    lines.append("// character of UCD 3.2.0 that has one, Hangul syllables excepted.")
    lines.append("var decompositions = []mapping{")
    emit_rows(lines, ["{0x%x, %s}," % (cp, go_string(m)) for cp, m in sorted(nfkd_map().items())], 4)
    lines += ["}", ""]
    lines.append("// combiningClasses are the non-zero canonical combining classes.")
    lines.append("var combiningClasses = []classSpan{")
    emit_rows(lines, ["{0x%x, 0x%x, %d}," % tuple(s) for s in ccc_spans()], 5)
    lines += ["}", ""]
    lines.append("// compositions are the canonical composition pairs, sorted.")
    lines.append("var compositions = []composition{")
    emit_rows(lines, ["{0x%x, 0x%x, 0x%x}," % p for p in composition_pairs()], 4)
    lines += ["}"]
    print("\n".join(lines))


DOTS = [".", "。", "．", "｡"]


def fixture_hosts(paths):
    hosts = set()
    for path in paths:
        with tarfile.open(path) as tar:
            for member in tar.getmembers():
                if not member.isfile() or not member.name.endswith(".json"):
                    continue
                if not any(k in member.name for k in ("profiles", "jump_hosts", "socks_proxies", "smb_shares")):
                    continue
                try:
                    data = json.load(tar.extractfile(member))
                except ValueError:
                    continue
                stack = [data]
                while stack:
                    v = stack.pop()
                    if isinstance(v, dict):
                        for key, value in v.items():
                            if key == "host" and isinstance(value, str):
                                hosts.add(value)
                            else:
                                stack.append(value)
                    elif isinstance(v, list):
                        stack.extend(v)
    return sorted(hosts)


def corpus(fixture_paths):
    rnd = random.Random(20031)
    names = set(fixture_hosts(fixture_paths))
    pools = {
        "latin": [chr(c) for c in range(0xC0, 0x250)],
        "marks": [chr(c) for c in range(0x300, 0x370)] + ["ཱ", "ི", "ྀ", "ְ", "ุ"],
        "b1": [chr(s) for s in (0xAD, 0x34F, 0x1806, 0x180B, 0x200B, 0x200D, 0x2060, 0xFEFF, 0xFE00, 0xFE0F)],
        "compat": ["①", "ﬁ", "㎒", "Ａ", "Ω", "Å", "ẛ", "Ǆ", "ﷺ", "և"],
        "bidi_r": [chr(c) for c in range(0x5D0, 0x5EB)] + [chr(c) for c in range(0x627, 0x64B)],
        "bidi_n": ["0", "1", "-", "٠", "۰", " ", "‎", "‪"],
        "hangul": [chr(c) for c in range(0x1100, 0x1113)] + [chr(c) for c in range(0x1161, 0x1176)]
        + [chr(c) for c in range(0x11A8, 0x11C3)] + ["가", "힣", "각"],
        "cjk": ["中", "文", "あ", "ア", "ｶﾞ", "　"],
        "greek": ["Σ", "σ", "ς", "ΐ", "ᾳ", "ᾀ", "ͅ"],
        "special": ["İ", "ı", "ß", "ẞ", "Ⅎ", "K", "�", "", "\U000e0001",
                    "\U0001d400", "\U00010400", "\U0010fffd", "͸", "ࢠ", "\U0001f600", "⿰", "̀"],
        "ascii": list("abcxyzABCXYZ019-_*"),
    }
    every = [c for pool in pools.values() for c in pool]
    for pool in pools.values():
        for c in pool:
            names.update({c, "a" + c, c + "b", "xn--" + c, "XN--" + c, c + ".de", "www." + c + ".example."})
    for _ in range(6000):
        pool = pools[rnd.choice(list(pools))]
        label = "".join(rnd.choice(pool if rnd.random() < 0.7 else every) for _ in range(rnd.randint(1, 8)))
        names.add(label)
        names.add(rnd.choice(["", "www", "Mail", "xn--abc"]) + rnd.choice(DOTS) + label + rnd.choice(["", ".com", "。jp", "."]))
    for _ in range(1500):
        base = rnd.choice(pools["latin"] + pools["ascii"] + pools["greek"] + pools["hangul"])
        marks = "".join(rnd.choice(pools["marks"]) for _ in range(rnd.randint(1, 6)))
        names.add(base + marks)
        names.add(base + marks + rnd.choice(pools["latin"]))
    for n in range(50, 70):
        names.add("ü" * (n // 8) + "a" * (n - n // 8))
        names.add("a" * n)
        names.add("ü" + "a" * n)
        names.add("­" * n + "ü")
        names.add("中" * (n // 3))
    names.update({"", ".", "..", "a..b", "ü..b", "ü.", "ü。", ".ü", "a" * 64 + ".de",
                  "bücher.example", "BÜCHER.example", "xn--bcher-kva.example", "münchen.de"})
    return sorted(names)


def vectors(fixture_paths):
    for name in corpus(fixture_paths):
        print(json.dumps({"in": name, "out": encode(name)}, ensure_ascii=False))


# Exhaustive checks: every code point in a few contexts, one SHA-256 per
# context over "<result>\n" lines, "!" for an error.
CONTEXTS = {
    "alone": "{}",
    "after_a": "a{}",
    "before_mark": "{}́",
    "in_rtl": "א{}א",
    "label": "{}.example",
}


def digests():
    out = {"python": sys.version.split()[0], "unicode": unicodedata.unidata_version}
    for name, form in CONTEXTS.items():
        h = hashlib.sha256()
        for cp in codepoints():
            r = encode(form.format(chr(cp)))
            h.update(("!" if r is None else r).encode() + b"\n")
        out[name] = h.hexdigest()
    print(json.dumps(out, indent=1))


def serve():
    for line in sys.stdin:
        print(json.dumps(encode(json.loads(line))), flush=True)


if __name__ == "__main__":
    mode = sys.argv[1] if len(sys.argv) > 1 else ""
    if mode == "tables":
        tables()
    elif mode == "vectors":
        vectors(sys.argv[2:])
    elif mode == "digests":
        digests()
    elif mode == "serve":
        serve()
    else:
        raise SystemExit("usage: oracle.py tables|vectors [fixture.tar ...]|digests|serve")
